import { useState } from 'react';
import { JxTagInput, JxChip, JxDivider } from '@jinx-ui/react';

interface ArticleTagsPickerProps {
  label?: string;
  defaultTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsPicker({
  label = 'Теги статьи',
  defaultTags = [],
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagsPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={apply}
      />

      <JxDivider label={`Выбрано: ${tags.length}`} />

      {tags.length === 0 ? (
        <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}>
          Пока ни одного тега
        </span>
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip
              key={tag}
              role="listitem"
              active
              removable
              onRemove={() => apply(tags.filter((item) => item !== tag))}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

